import{_ as s,o as e,c as i,a3 as p}from"./chunks/framework.BwzYn71E.js";const g=JSON.parse('{"title":"针对理想系统的压缩算法","description":"","frontmatter":{"translationSource":{"title":"针对理想系统的压缩算法","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZllGoCkftlEvd5lMExXrO2","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}]]},"headers":[],"relativePath":"zh/compression-algorithms-for-implementing-idealized-systems.md","filePath":"zh/page-ZllGoCkftlEvd5lMExXrO2.md"}'),c={name:"zh/compression-algorithms-for-implementing-idealized-systems.md"};function t(o,a,l,d,r,n){return e(),i("div",null,[...a[0]||(a[0]=[p('<div class="logistics-content"><h1 id="针对理想系统的压缩算法" tabindex="-1">针对理想系统的压缩算法 <a class="header-anchor" href="#针对理想系统的压缩算法" aria-label="Permalink to &quot;针对理想系统的压缩算法&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>本页内容更新：</span><a href="/endfield-skydoc/zh/changelog/capture-2026-11-08T14-43-43-693Z-b04528fe" title="网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。" aria-label="本页内容更新：2026-11-08. 网站最近同步到本页内容变更的时间（北京时间），不代表源作者实际编辑时间。点击查看更新记录。"><time datetime="2026-11-08T14:43:45.228Z">2026-11-08</time></a><span class="page-updated-zone">（北京时间）</span></p><blockquote><p>源页面 ID：<code>ZllGoCkftlEvd5lMExXrO2</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZllGoCkftlEvd5lMExXrO2" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><blockquote><p>人脑搭产线就是在用启发式算法</p><p>——恒星泰斗</p></blockquote><p><img src="/endfield-skydoc/logistics/src/assets/images/img-54076b3e7fa770ef.gif" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="14pcS9WHvs8xfrSPSKnc53"><p><s>镇楼</s></p></div><p><span id="source-block-wW6QHfP1USjLEMladjHekj"></span></p><h3 id="人类是怎么布局的" tabindex="-1">人类是怎么布局的？ <a class="header-anchor" href="#人类是怎么布局的" aria-label="Permalink to &quot;人类是怎么布局的？&quot;">​</a></h3><p><span id="source-block-uaL3SZXJvWRi8tCAOsKjg9"></span></p><h4 id="以-325-799-为例" tabindex="-1">以 325/799 为例 <a class="header-anchor" href="#以-325-799-为例" aria-label="Permalink to &quot;以 325/799 为例&quot;">​</a></h4><p><span id="source-block-kFyTivAiZwVCBBDDmZ3OQJ"></span></p><h5 id="草稿-draft" tabindex="-1">草稿（Draft） <a class="header-anchor" href="#草稿-draft" aria-label="Permalink to &quot;草稿（Draft）&quot;">​</a></h5><p>话不多说我们先上 TopoFlow 图。最开始我们一般会拿到一个杂乱无章的图：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b26da58bb5f04a11.q90-d24c93e9df94f8ff.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="DdSBxHf2fCU3iPzs7yPfuW"><p>！？325/799？！</p></div><p>第一步我们会对图进行整理，使得它的平面化“看起来”相对容易，例如这样：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9e959ae217340ca1.q90-a0b813a9e8f78bb0.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="TMveqqiN4IZUgY7ToSXerV"><p>整理后的 325/799</p></div><p>我们可以称这样的一个粗布局为 Draft，观察这个 Draft，我们可以看到几个特征：</p><p>下一步就是根据 Draft 在实际游戏中布局。</p><p><span id="source-block-56Px6IMF9G9gnl3BSVCKDq"></span></p><h5 id="第一轮" tabindex="-1">第一轮 <a class="header-anchor" href="#第一轮" aria-label="Permalink to &quot;第一轮&quot;">​</a></h5><p>首先放置源和汇，以及直接连接源和汇的原件：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-edd6d4d22e064b37.q90-b132f874ac08915f.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="LqSjfxUrd0bWsxr2XDA6Zf"><p>step 1</p></div><p>然后考虑主链的放置：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c0e58cf38e27983c.q90-4a899754e9a1e6bd.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="SRq5GAHG4AiG9p8Zu6BuU8"><p>step 2</p></div><p>为了布局方便，我们拆开下侧的三汇流（经验证流量不变），得到：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ff889173e26b66d9.q90-7346467662fc572b.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="76ar2gsl1y8wNqCRPleDBG"><p>step 3.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2c152ddcb9542bce.q90-f110626c65a3809a.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="jwCzlI8G1gycgxqNyT2l6w"><p>step 3.2</p></div><p>继续拆分下侧三汇流：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9f8db3e6ea188340.q90-f06a7a4e0ca9099b.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="3xEMQlKU5Y2tTygkPi5IO5"><p>step 4.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6694e35523aed094.q90-a4ae0147fd549257.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="ciPPIHvGx6qDWHfEi6vgSN"><p>step 4.2</p></div><p>这里有一个重要的观察：原件的朝向是可以在连接传送带的过程中动态修改的，即一开始的原件不应该拥有“朝向”这个属性</p><p>随后布局上侧汇流单元：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-aa304f3647f6ffeb.q90-1ccbf4ed31c566d7.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="qhJmout6Jgi8W97nJ219cz"><p>step 5</p></div><p>继续布局：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-81adb66e7f074d5d.q90-c1bea0c1892e2940.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="0VekmVzjrBjDbEUYn7Q07n"><p>step 6.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-796819c117d7fa9d.q90-1162a83edb598462.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="yurtIy4ealBxnxe0TNL6vQ"><p>step 6.2</p></div><p>此时发现左下角汇流器 → 右上角汇流器的连接已经无法建立，于是对布局进行修改：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-74af56a032e69980.q90-fa8dda4de129366c.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="hyBjG3YMQ4G9hwKyRMZFCB"><p>step 7.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-314f4c058d985449.q90-e2cc2b697ef3dc45.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="HZfOj6mEyi8gk6KGkS04bY"><p>step 7.2</p></div><p>接着完成最后的连接：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-55b86b0962b61116.q90-b6dfae1c76fd940b.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="lkguqyYn4PjZQedkl0fpeg"><p>step 8</p></div><p>于是我们得到了第一个可行的布局（面积 110，原件数 34，经过流量仿真，周期流量确实是 325/799）</p><p><span id="source-block-trnc79pKkAzcvat5lLwPk4"></span></p><h5 id="第二轮" tabindex="-1">第二轮 <a class="header-anchor" href="#第二轮" aria-label="Permalink to &quot;第二轮&quot;">​</a></h5><p>显然第一轮的结果看起来很丑陋，我们考虑回退并重新布局上侧：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5cb8abd6b0d33c7c.q90-dddecc18c51812c9.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="gCtHP9Ii5zAjWJXjxXtlTR"><p>step 1</p></div><p>继续：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0b51f713ecc097dc.q90-62ca9a3c91276ecd.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="M3yqNmUq37TqEWB8T4JoLB"><p>step 2</p></div><p>上侧地方吃紧，考虑对图进行修改：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3348f44656e3e6fa.q90-8c8c073131fb0eba.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="VfRaDArr8CfUVcoNSNo4Xe"><p>step 3.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abc81101899179b5.q90-df3c35e0a6263165.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="MTzRT8j69JFR2h3PxUkJSc"><p>step 3.2</p></div><p>继续：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8caea85c91e316b2.q90-f210f728f3bd2b07.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="5F9xN7hbpeMQOW823RLI7s"><p>step 4</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-04e7961f2ab79336.q90-11fcc3a56c338ac4.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="I29O44Z0BA0H8ErrNDqLN6"><p>step 5</p></div><p>第二个可行布局（面积 99，原件数 31，经过流量仿真，周期流量确实是 325/799）</p><p><span id="source-block-W3WqdXD4YJV2s5YwNQy4Rv"></span></p><h5 id="第三轮" tabindex="-1">第三轮 <a class="header-anchor" href="#第三轮" aria-label="Permalink to &quot;第三轮&quot;">​</a></h5><p>回退上侧：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cbdbdfe32553503b.q90-13dc059be757a0c9.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="Ke1GSBELTSu8dhMHKBWVcp"><p>step 1</p></div><p>拆分汇流器：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3ee61b72412b1958.q90-3720e4914eadfcc7.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="3dLtm8HZ35Edwsmuvr0BHZ"><p>step 2.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-84f3a8a6d9213725.q90-85761b021248f088.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="NfQKc3CrCMXzXRE1N1KATU"><p>step 2.2</p></div><p>最后完善一下：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ef9d7525a6a8eae2.q90-35025034d085d9b2.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="AWb554q2yv7aMNachZbUlZ"><p>step 3</p></div><p>得到了一个还不错的整体布局（面积 88，元件数 32，经过流量仿真，周期流量确实是 325/799）</p><p><span id="source-block-oBffoBBBm5SHKIwM8ww0k2"></span></p><h4 id="在这期间-我们做了哪些操作" tabindex="-1">在这期间，我们做了哪些操作？ <a class="header-anchor" href="#在这期间-我们做了哪些操作" aria-label="Permalink to &quot;在这期间，我们做了哪些操作？&quot;">​</a></h4><p>首先，我们通过“直觉”和“经验”设计了一个“看起来不错”的 Draft；</p><p>其次，我们基本只通过以下三个操作（当然，还有一些局部的修复动作以及回退）</p><p>值得注意的是，我们的每一次操作几乎都基于上一次操作的结果，整个布局过程是树状生长的（这也许也是随机/遗传算法效率较低的原因，毕竟我们的剪枝更激进）；</p><p><span class="mark-red"><s>其实我写完了才发现上面的 325-799 布局的 In 箱子意外连接了另一个汇流器……但我真的不想再画一遍了😡😡😡</s></span></p><p><span id="source-block-VEcokFaAbFbe38SaF0xp8M"></span></p><h3 id="将这些过程翻译成用于指导启发式搜索的搜索策略" tabindex="-1">将这些过程翻译成用于指导启发式搜索的搜索策略 <a class="header-anchor" href="#将这些过程翻译成用于指导启发式搜索的搜索策略" aria-label="Permalink to &quot;将这些过程翻译成用于指导启发式搜索的搜索策略&quot;">​</a></h3><p>直接构造一个全局搜索器，一次决定所有布局变量，会遇到三个问题：状态空间过大、失败反馈滞后、重试丢弃已经满足的约束。因此问题可以改写为：如何把布局过程拆成一系列可局部回滚的决策。</p><p>决策顺序是：结构选择、坐标分配、端口与路径分配。每一步产生一个部分状态；失败时回滚到最近的稳定状态。对应到算法，就是 Draft、PartialState、feedback 和 compaction 四个组件。</p><p>目标是最小化 (Area, N_logic + N_X)，其中 N_logic 是逻辑节点数，N_X 是交叉单元数；候选还必须通过几何、路径和流量约束。搜索在部分状态空间进行，不直接搜索完整布局空间。</p><p><span id="source-block-MmG8052WMwPMW5Yplp6t9M"></span></p><h4 id="draft-结构先验" tabindex="-1">Draft：结构先验 <a class="header-anchor" href="#draft-结构先验" aria-label="Permalink to &quot;Draft：结构先验&quot;">​</a></h4><p>布局先确定结构，再确定坐标：哪条链作为主轴、汇流器如何分到两侧、源汇核心靠近哪一端。这个结构模板就是 Draft。</p><p>Draft 是图导出的紧凑结构模板，基于拓扑排序生成。它给出主轴、回流分组、源汇核心和终端方向，但不构成坐标解。结构确定后，后续搜索的坐标空间才被限制在合理区域。</p><p>如图所示是算法给出的 325/799 的五个 Draft：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fc1fb4635c2932b8.q90-baa89aa2b6e7aaef.webp" alt="针对理想系统的压缩算法"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-42f1e74806485acc.q90-8a2407e46b4b295b.webp" alt="针对理想系统的压缩算法"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-de86e22d181d8964.q90-9be43bb16ce9abe3.webp" alt="针对理想系统的压缩算法"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9880e830f5ffc2e9.q90-28e101b1f4222063.webp" alt="针对理想系统的压缩算法"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9c6f3cd7792d5468.q90-688e4edc08d7abcf.webp" alt="针对理想系统的压缩算法"></p><p><span id="source-block-UHhN3yCWhGQZnmKs7bZoXc"></span></p><h5 id="主轴发现" tabindex="-1">主轴发现 <a class="header-anchor" href="#主轴发现" aria-label="Permalink to &quot;主轴发现&quot;">​</a></h5><p>主轴有两条生成路径：</p><p>第一条路径沿着分流器链构造主轴；第二条路径利用设备之间的直接接触关系，把可贴合的节点串成接触链。两条路径最终都给出一个有序节点序列，作为后续放置的骨架。</p><p><span id="source-block-LVCOtpX0WM7SPnUmQA3Jqa"></span></p><h5 id="回流分配" tabindex="-1">回流分配 <a class="header-anchor" href="#回流分配" aria-label="Permalink to &quot;回流分配&quot;">​</a></h5><p>主轴确定后，需要把回流汇流器分配到主轴两侧。</p><p>间距过小会增加回流路径冲突，间距过大则扩大包围盒。分配时先按连通关系对非主轴汇流器分组，再以组为单位分配到 upper 或 lower bank。这样能保持回流链的连通性，减少跨区绕行。</p><p>侧别分配还需要消除镜像对称：把所有组翻到另一侧会得到同一布局的镜像，不应重复搜索。实现上固定第一组的侧别，只枚举其余组；小图直接枚举，大图使用确定性的平衡前缀 Beam。</p><p>分配完成后按结构指标排序，包括跨 bank 边数、bank lane 峰值负载、设备到主轴的附着跨度、估计交叉数和面积下界。排序时保留最长主轴的候选，避免短主轴候选过早占据 Beam。</p><p><span id="source-block-edrIa9oQcN40ZgwjXCoHSH"></span></p><h5 id="源汇锚点" tabindex="-1">源汇锚点 <a class="header-anchor" href="#源汇锚点" aria-label="Permalink to &quot;源汇锚点&quot;">​</a></h5><p>构造初期通常先固定终端和与终端直接相连的设备。原因是终端位于包围盒外一格，位置、朝向和端口都受约束；终端确定后，内部设备才有稳定的坐标参照。</p><p>对应地，算法先找 source anchor 和 sink anchor，把与终端直接相连的设备收进 core，再围绕这个核心生成 Draft。终端确定过晚，内部设备已经展开，重新满足约束的代价高；确定过早或缺乏依据，又会限制主轴的位置。</p><p><span id="source-block-Ehv613wB81TvuUWAktdsiH"></span></p><h5 id="模板物化" tabindex="-1">模板物化 <a class="header-anchor" href="#模板物化" aria-label="Permalink to &quot;模板物化&quot;">​</a></h5><p>Draft 只描述相对关系，还没有坐标。进入搜索前，需要把 spine、upper、lower、core 转换成无碰撞的单位网格模板：</p><p>模板只作为初始候选，不作为可行布局。它不保证端口充足，也不保证路径可达；作用是把搜索限制在结构上可能紧凑的区域。</p><p><span id="source-block-f8NzRY3rVhZD3JnVumHRkW"></span></p><h5 id="多-draft" tabindex="-1">多 Draft <a class="header-anchor" href="#多-draft" aria-label="Permalink to &quot;多 Draft&quot;">​</a></h5><p>同一张图可能存在多个合理的结构方案：主轴可以沿 splitter 链，也可以沿接触链；回流可以位于上侧或下侧；源汇核心可以靠近一端，也可以跨两端布置。</p><p>因此算法从单个 Draft 改为生成一组候选：普通 splitter 主轴、contact-chain 主轴、paired core、compressed bank、return lane、folded/staircase 变体，以及少量拓扑改写后的图。</p><p>实际构造通常需要比较多个结构版本：先验证主轴，再调整回流，最后决定是否拆分三汇流。算法把这些版本变成并行候选，避免串行重试。</p><p><span id="source-block-AwzuYNMq8zZh2tpzckyHsT"></span></p><h4 id="部分状态-增量构造与局部回滚" tabindex="-1">部分状态：增量构造与局部回滚 <a class="header-anchor" href="#部分状态-增量构造与局部回滚" aria-label="Permalink to &quot;部分状态：增量构造与局部回滚&quot;">​</a></h4><p>一次性确定全部坐标不可行。放置与布线需要交替推进，失败时回滚到最近的稳定状态。因此搜索状态不能是完整布局，而必须是“已经完成到哪一步”的部分布局。</p><p>这就是 PartialState：记录已放置设备、朝向、已布路径、deferred 边和最近一次失败。每个搜索节点对应一个部分状态，子状态在独立的 RouteWorld 上构造，失败不会污染父状态。</p><p><span id="source-block-a9eTtnUbxXLShN9HpGGmGT"></span></p><h5 id="放置-以接触链为扩展单元" tabindex="-1">放置：以接触链为扩展单元 <a class="header-anchor" href="#放置-以接触链为扩展单元" aria-label="Permalink to &quot;放置：以接触链为扩展单元&quot;">​</a></h5><p>单设备扩展容易产生短视决策：当前坐标可行，但会占用后续端口和走廊资源。</p><p>更有效的扩展单元是接触链。macro / chain expansion 一次放置一条接触链，失败时尝试更短的前缀；整条链不可放置时，回滚到链的局部，不重置整个布局。</p><p><span id="source-block-7ZaL35XKI91MHQuHF4k7aP"></span></p><h5 id="排序-完成度优先" tabindex="-1">排序：完成度优先 <a class="header-anchor" href="#排序-完成度优先" aria-label="Permalink to &quot;排序：完成度优先&quot;">​</a></h5><p>Beam 的排序使用完成度启发式：未放置设备越少越优先，已连边越多越优先，当前包围盒越小越好，S→C 间距不足要惩罚，设备离 Draft 模板越近越优先。</p><p>它优先扩展完成度高的状态，避免均匀遍历所有可能。</p><p><span id="source-block-LcU7KvQYp1lssvqBuwN1Ng"></span></p><h5 id="延迟定向" tabindex="-1">延迟定向 <a class="header-anchor" href="#延迟定向" aria-label="Permalink to &quot;延迟定向&quot;">​</a></h5><p>第一节提到一个关键约束：设备在初始阶段不应固定朝向，朝向应由后续路径的端口需求决定。</p><p>late orientation 对应这一约束：根节点只固定一个初始方向，后续设备的方向不提前锁定，等路由确定端口后再确定。这样，早期方向选择不会迫使后续路径绕行。</p><p>先保留结构上的可能性，再逐步确定几何关系。这个顺序贯穿整条 pipeline。</p><p><span id="source-block-gyrOE6wv51aDv3EotxrH1E"></span></p><h4 id="共享前沿-全局队列与状态去重" tabindex="-1">共享前沿：全局队列与状态去重 <a class="header-anchor" href="#共享前沿-全局队列与状态去重" aria-label="Permalink to &quot;共享前沿：全局队列与状态去重&quot;">​</a></h4><p>单分支扩展只解决单个搜索子树的推进。一张图存在多个结构方案，单个 Draft 也不一定最优。</p><p>如果 16 个 worker 各自从零开始，会重复探索相同状态，也会重复触发相同失败。共享优先队列的做法是：任意 worker 可以继续其他 worker 留下的部分状态；状态用平移归一化后的 key 去重；不同 Draft、拓扑和反馈源使用独立上下文标识。</p><p>16 个 worker 共享同一搜索前沿，避免各自独立重启。最多 4 个 Draft 组同时活跃，每组最多 2 个扩展在飞，4 个 worker 同时执行压缩，最多 4 个辅助任务准备新的 Draft 或拓扑变体。组停滞时挂起而非删除；等其他组让出槽位后可以继续。</p><p>随机重启或遗传算法的多样性发生在完整解层：先生成完整个体，再筛选。这里的多样性发生在部分状态层：不同 Draft 是不同搜索子树，Beam 可以在部分状态上剪枝；一条链不可放置时，不需要等整张图完成才淘汰。剪枝更早，浪费更少。</p><p><span id="source-block-kZW4tVuVT1wE5GwPr5Yfwt"></span></p><h4 id="反馈-基于失败诊断的局部重开" tabindex="-1">反馈：基于失败诊断的局部重开 <a class="header-anchor" href="#反馈-基于失败诊断的局部重开" aria-label="Permalink to &quot;反馈：基于失败诊断的局部重开&quot;">​</a></h4><p>搜索受挫时，不应重置全部决策。更合理的做法是回滚到最近的稳定状态，只重开上部结构或单个汇流器。</p><p>feedback 对应这一机制：从已通过验证的布局出发，保留大部分设备位置、朝向和已布路径，只打开诊断指出的、或结构上值得重开的局部区域：</p><p>反馈种子来自失败诊断和当前布局的接触关系：失败边、阻挡边、被占格、相邻机器、空行/空列。算法只在这些证据指向的局部区域重开，避免重新随机化整个布局。</p><p>默认情况下，反馈源优先使用压缩后的成熟布局：Beam 解先经过一轮压缩，再把结果作为下一轮反馈的起点；如果压缩没有改进，才回退到原始验证布局。反馈同时按代、按 family、按来源限量，避免单个局部问题消耗全部预算。</p><p><span id="source-block-YvGjYKCxE8z4lwQeGfSZNT"></span></p><h4 id="硬核压缩-确信" tabindex="-1">硬核压缩（确信） <a class="header-anchor" href="#硬核压缩-确信" aria-label="Permalink to &quot;硬核压缩（确信）&quot;">​</a></h4><blockquote><p>想象一堆被卡在网格里的豆腐块通过软软的传送带相互连接<br> 然后受到一个向着中心的吸引力<br> 然后来一阵 shake shake<br> 模块就变小了<br> 😆</p><p>——曜</p></blockquote><p>首个可行布局生成后，面积通常仍有下降空间。第一节的三轮迭代把面积从 110 降到 99，再降到 88，依靠的是在已有布局上回退、拆合和重连。</p><p>算法分为构造和压缩两个阶段。构造阶段只要求尽快得到 gate-valid 布局，不追求最小面积。压缩阶段只对合法布局做局部改进：连续压缩器把机器和传送带拐点视为可移动锚点，先用物理松弛收紧布局，再投影回整数网格，最后用 A* 重布线。</p><p>为什么不在构造阶段压缩？非法布局的面积没有意义。布局可能更紧，但端口不足、路径交叉非法或终端流量不匹配，目标值再小也不可行。先把合法布局构造出来，再在可行域内压缩，顺序才成立。</p><p>压缩会移动机器，也可能创建或销毁 capacity-0 的紧贴连接。因此压缩之后必须重新执行完整物理图门禁。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2ce491e7123ed178.gif" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="X12Xu3Dbaj64ZPmHbkHpfD"><p>神秘压缩小动画</p></div><p><span id="source-block-20rTLlKbnexxe40S0vzFpN"></span></p><h4 id="小图快速通道" tabindex="-1">小图快速通道 <a class="header-anchor" href="#小图快速通道" aria-label="Permalink to &quot;小图快速通道&quot;">​</a></h4><p>小规模图通常不需要复杂启发式，可以直接尝试有限的几种放置。</p><p>搜索保留三类精确分支：</p><p>这些分支作为主搜索的补充，原则是“能枚举就别猜”。启发式搜索存在适用边界，承认问题规模、在合适的时候换更精确的方法，本身就是设计的一部分。</p><p>为什么不把所有图都交给全局 MILP/CP-SAT？变量规模会随网格、边数和路径长度迅速膨胀，完整流量语义还包含 simulator 的周期行为和 n-to-n，很难用静态约束直接表达。</p><p><span id="source-block-1gGVSlUEoo7ElcC7ACHYzk"></span></p><h4 id="流量验证" tabindex="-1">流量验证 <a class="header-anchor" href="#流量验证" aria-label="Permalink to &quot;流量验证&quot;">​</a></h4><p>候选布局生成后，必须在游戏语义下验证流量。</p><p>门禁按固定顺序检查：</p><p>任何一步失败、超时、oracle 错误，都返回 unknown，不会降级成 valid。</p><p>门禁不只是工程细节。它决定了搜索能有多大胆：搜索可以启发式，发布必须可证明。没有这层门禁，前面所有启发式都可能把非法布局推到用户面前；有了它，搜索才可以大胆试错。</p><p><span id="source-block-8m9XxLJ9ioxJXOtmlTj0S0"></span></p><h3 id="还没解决的问题" tabindex="-1">还没解决的问题 <a class="header-anchor" href="#还没解决的问题" aria-label="Permalink to &quot;还没解决的问题&quot;">​</a></h3><ul><li><p>反馈并非普遍增益：在某些图上，它会拖慢首解，甚至降低首解率。当前默认来自筛选，不能当定理。</p></li><li><p>多 worker 的结果无法逐位复现：完成顺序会改变哪些任务在 deadline 前进入。</p></li><li><p>连续压缩依赖 Node 和浏览器原型脚本；缺失时只能保持 incumbent。</p></li><li><p>小图精确分支只覆盖很小的规模；更大的图仍然依赖启发式。</p></li><li><p>拆分类拓扑改写会增加节点，可能改善可布性，却让第二目标变差；何时值得改仍需实验回答。</p></li><li><p>参考布局中的“直觉”尚未完全形式化：已知需要关注走廊、端口、接触链和回流，但各因素的权重仍由搜索排序和实验调参决定。</p></li></ul><p><span id="source-block-odVp5F1OTsOVcgPtSBlzUx"></span></p><h3 id="更小和更稳定-以及一些结果展示" tabindex="-1">更小和更稳定，以及一些结果展示 <a class="header-anchor" href="#更小和更稳定-以及一些结果展示" aria-label="Permalink to &quot;更小和更稳定，以及一些结果展示&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4a3becc542521e50.q90-612c947bbbf40814.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="g0fDVZsErGshPjVRdRjFJz"><p>超越人工队！（虽然我感觉人工队根本没认真压缩😡😡😡）</p></div><p>当前的求解器很适合在短时间内快速给出极其优秀的布局方案，但不保证长时间下方案能持续得到优化直至逼近最优，也没有穷举解空间的能力。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b89be2470af17b79.q90-b42819225be4b1b1.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="tYu5H8y2k4IHVQIkTv4syf"><p>虽然但是其实我们不知道是否有比 88 更好的解</p></div><p>更好的做法是用本算法在快速生成原型布局，随后使用穷举的通用算法进行优化。</p><p>还有我想要无穷无尽的 CPU 核心😭😭😭😭😭快给我 CPU😭😭😭😭😭我要 HPC 集群😭😭😭😭😭😭😭😭GPU 我也要😭😭😋😭😭😭算力大短缺😭😭😭😭😭求求了快给我吧我什么都会做的😭😭😭😭</p></div>',1)])])}const m=s(c,[["render",t]]);export{g as __pageData,m as default};
